def calc_dosage(pedigree):
    """
    pedigree: list of (sire_name, generation) tuples, generation in {1,2,3,4}.
    Returns dict with keys dp, DI, CD.
    """
    gen_weight = {1: 16, 2: 8, 3: 4, 4: 2}
    cats = ["B", "I", "C", "S", "P"]
    dp = {c: 0.0 for c in cats}

    for sire, gen in pedigree:
        if sire not in CHEFS:
            continue
        w = gen_weight.get(gen, 0)
        for cat, frac in CHEFS[sire].items():
            dp[cat] += w * frac

    total = sum(dp.values())
    if total == 0:
        return {"dp": dp, "DI": float("nan"), "CD": float("nan")}

    half_c = dp["C"] / 2.0
    numerator_di   = dp["B"] + dp["I"] + half_c
    denominator_di = half_c + dp["S"] + dp["P"]
    DI = numerator_di / denominator_di if denominator_di &gt; 0 else float("inf")

    CD = (2 * dp["B"] + dp["I"] - dp["S"] - 2 * dp["P"]) / total

    return {"dp": dp, "DI": round(DI, 3), "CD": round(CD, 3)}


The formula follows Roman (1981). When the denominator of DI equals zero, the horse is classified as purely speed-oriented and DI is set to infinity.
